import{_ as i,o as e,c as n,a2 as _}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"It’s Alive! Image Live Migration, Live Import and Instant Restore with Ceph RBD - Danny Harnik, IBM","description":"","frontmatter":{"title":"It’s Alive! Image Live Migration, Live Import and Instant Restore with Ceph RBD - Danny Harnik, IBM","date":"2023-05-05T00:00:00.000Z","updated":"2023-05-05T00:00:00.000Z","tags":["Ceph","Live Migration","Image Import","Instant Restore","RBD"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/It_s_Alive_Image_Live_Migration_Live_Import_and_Instant_Restore_with_Ceph_RBD_-_Danny_Harnik_IBM.md","filePath":"posts/2023/It_s_Alive_Image_Live_Migration_Live_Import_and_Instant_Restore_with_Ceph_RBD_-_Danny_Harnik_IBM.md","lastUpdated":1780459816000}'),a={name:"posts/2023/It_s_Alive_Image_Live_Migration_Live_Import_and_Instant_Restore_with_Ceph_RBD_-_Danny_Harnik_IBM.md"};function r(o,t,l,s,p,g){return e(),n("div",null,[...t[0]||(t[0]=[_('<h3 id="改进后的中文总结" tabindex="-1">改进后的中文总结 <a class="header-anchor" href="#改进后的中文总结" aria-label="Permalink to &quot;改进后的中文总结&quot;">​</a></h3><p><strong>会议主题</strong>：使用Ceph RBD进行图像实时迁移、导入和即时恢复</p><p><strong>会议时间</strong>：[具体时间]</p><p><strong>会议地点</strong>：[具体地点]</p><p><strong>参会人员</strong>：来自IBM研究（Haifa, Israel）的研发团队成员，包括发言人Danny Harnik及其同事Effie。</p><p><strong>会议内容总结</strong>：</p><ol><li><p><strong>图像实时迁移（Image Live Migration）</strong></p><ul><li>自Nautilus版本开始引入，支持同一集群内不同存储池之间的图像迁移，Pacific版本扩展到外部源。</li><li>仅支持Librbd，适用于OpenStack、KVM虚拟化等。</li><li>使用后复制迁移技术，允许在数据迁移过程中立即在目标端开始工作。</li><li>主要应用场景包括集群间实时迁移、即时导入到Ceph和备份与即时恢复。</li></ul></li><li><p><strong>外部NBD源的实时迁移</strong></p><ul><li>新增NBD格式支持，通过chemo NBD服务器连接，实现更灵活的图像导入。</li><li>提供备份与即时恢复的POC，使用qcow2格式进行差异备份，并通过chemo NBD实现即时恢复。</li></ul></li><li><p><strong>未来计划与改进方向</strong></p><ul><li>推动现有PR上线的进程。</li><li>探索对克隆图像的集群间迁移支持。</li><li>改进备份与恢复流程，特别是增加对Ceph原生导出格式的索引支持，以实现更高效的即时恢复。</li></ul></li></ol><p><strong>决定事项</strong>：</p><ul><li>继续推动图像实时迁移功能的开发和优化。</li><li>完善文档和教程，确保用户能够充分利用新功能。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>完成并上线相关PR。</li><li>开发和测试对克隆图像的集群间迁移支持。</li><li>研究和实施对Ceph原生导出格式的索引支持，以优化备份与恢复流程。</li></ul><p><strong>会议结束</strong>：</p><ul><li>会议在提问和讨论环节后圆满结束，发言人感谢所有参与者的积极参与和反馈。</li></ul>',13)])])}const m=i(a,[["render",r]]);export{d as __pageData,m as default};
